#!/system/bin/sh
# SPDX-License-Identifier: Apache-2.0
# Copyright 2026 The Googlebook OS build (GB-build) authors.
#
# gb_vnni.sh -- OPTIONAL runtime sha256 guard for the VNNI libz patch.
#
# The default integration (vnni.rc, generated by vnni_patch.py --out-rc) binds the
# patched libz from init ONLY when the partition's build fingerprint equals the
# build it was patched for (`on early-init && property:ro.<part>.build.fingerprint=`).
# That gate is what keeps an A/B OTA'd slot -- which gb_slotsync boots with the
# SAME initrd/odm tree -- from getting this build's libz.  This script is an
# additional, stricter variant: it binds the patched copy over each destination
# ONLY when the destination's current sha256 still equals the value the patch was
# built against, so it can never apply to bytes it was not proven against.
#
# Manifest format (/odm/vnni/guard.tsv), one target per line, tab-separated:
#   <dest-path>\t<orig_sha256>\t<odm-src-path>
#
# Run it as an init 'exec_start' oneshot in 'on early-init' (synchronous, before
# zygote), INSTEAD of the init-builtin binds.  It needs a domain allowed to read
# the destinations, mount over them and relabel; both trees currently boot with
# androidboot.selinux=permissive, and the pipeline's other oneshots use
# u:r:shell:s0 (see INTEGRATION.md section 3).
set -u
LOG=/dev/kmsg
TSV=/odm/vnni/guard.tsv
TB=/system/bin/toybox
say() { echo "gb_vnni: $*" > "$LOG" 2>/dev/null; }
[ -r "$TSV" ] || { say "no $TSV; nothing to do"; exit 0; }
n_ok=0 n_skip=0
while IFS="$(printf '\t')" read -r dest want src; do
    [ -n "$dest" ] || continue
    case "$dest" in \#*) continue;; esac
    [ -f "$dest" ] || { say "skip $dest (absent)"; n_skip=$((n_skip + 1)); continue; }
    [ -f "$src" ]  || { say "skip $dest (no src $src)"; n_skip=$((n_skip + 1)); continue; }
    have=$($TB sha256sum "$dest" 2>/dev/null | $TB cut -d' ' -f1)
    if [ "$have" = "$want" ]; then
        $TB restorecon "$src" 2>/dev/null
        # toybox mount syntax (NOT init's "mount none SRC DST bind")
        if $TB mount -o bind "$src" "$dest" 2>/dev/null; then
            $TB restorecon "$dest" 2>/dev/null
            $TB mount -o remount,bind,ro "$dest" 2>/dev/null || say "WARN $dest left read-write"
            say "applied $dest"
            n_ok=$((n_ok + 1))
        else
            say "FAILED bind $dest"
            n_skip=$((n_skip + 1))
        fi
    else
        say "skip $dest (sha256 $have != $want)"
        n_skip=$((n_skip + 1))
    fi
done < "$TSV"
say "done: applied=$n_ok skipped=$n_skip"
exit 0
